@startuml

class Employee {
  + name : string
  + department : string
  + staffNumber : int
}

class IdentityCard {
  + cardNumber : int
}

class GuestCard {
  + cardNumber : int
  + current_date : date
}

class Car {
  + vehicleNumber : int
}

class CardReader {
  + verify(cardNumber : int) : boolean
}

class Barrier {
  + rise() : void
}

class CarPark {
  + isFull() : boolean
}

class Sign {
  + displayStatus(status : string) : void
}

class Reception {
  + collect(card : GuestCard) : void
}

IdentityCard "1" -- "1" Employee
GuestCard "0..*" -- "1" Reception
Car "1" -- "1" CardReader : uses
CardReader "1" --> "1" Barrier : triggers
CarPark "1" -- "1" Sign : displays status
CarPark "1" -- "*" Car : contains

@enduml

